import { verifyMessage } from "viem"

async function verifySiwe(message, signature, claimedAddress, expectedNonce) {
  const parsed = parseSiweMessage(message)
  if (parsed.expirationTime && Date.now() > parsed.expirationTime) throw new Error("expired")
  if (parsed.domain !== EXPECTED_DOMAIN) throw new Error("domain mismatch")

  const valid = await verifyMessage({ address: claimedAddress, message, signature })
  if (!valid) throw new Error("invalid signature")

  if (parsed.nonce !== expectedNonce || isNonceConsumed(parsed.nonce)) throw new Error("bad nonce")
  markNonceConsumed(parsed.nonce)

  return issueSession(claimedAddress)
}

