function testFuzz_cannotWithdrawMoreThanBalance(uint256 depositAmount, uint256 withdrawAmount) public {
    depositAmount = bound(depositAmount, 1, 1e24);
    token.mint(user, depositAmount);
    vm.prank(user); token.approve(address(vault), depositAmount);
    vm.prank(user); vault.deposit(depositAmount);

    if (withdrawAmount <= depositAmount) {
        vm.prank(user); vault.withdraw(withdrawAmount);
        assertEq(vault.balanceOf(user), depositAmount - withdrawAmount);
    } else {
        vm.expectRevert();
        vm.prank(user); vault.withdraw(withdrawAmount);
    }
}

